package main
enum E { A, B, }
var trace string
func none()Option[int]{trace+="N";return Option[int]::None}
func outer(e E)Option[int]{
 inner:=func()Option[int]{
  trace+="I"
  xs:=[]int{match e{E::A=>none()?,E::B=>2}}
  trace+="bad"
  return Option[int]::Some(xs[0])
 }
 _=inner()
 trace+="O"
 return Option[int]::Some(9)
}
func main(){
 got:=outer(E::A)
 match got {Option[int]::Some(n)=>{if n!=9{panic("outer value")}},Option[int]::None=>{panic("wrong user frame")},}
 if trace!="INO"{panic(trace)}
}
